def transform(grid):
    # A solid foreground run beginning at the left edge is extended across
    # the trailing background suffix in color 1; full-width bars stay as-is.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = next(v for v, _ in Counter(x for row in grid for x in row if x != bg).most_common(1))
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if row and row[0] == fg:
            end = 0
            while end < len(row) and row[end] == fg:
                end += 1
            if end < len(row) and all(v == bg for v in row[end:]):
                for c in range(end, len(row)):
                    out[r][c] = 1
    return out

