def transform(grid):
    # From a foreground pixel, continue along diagonal background rays when
    # an identical foreground pixel lies beyond the gap; fill the gap with 1.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = [v for row in grid for v in row if v != bg]
    fg = Counter(colors).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != fg:
                continue
            for dr, dc in ((1,1),(1,-1),(-1,1),(-1,-1)):
                y,x=r+dr,c+dc
                while 0<=y<h and 0<=x<w and grid[y][x]==bg:
                    y+=dr; x+=dc
                if 0<=y<h and 0<=x<w and grid[y][x]==fg:
                    yy,xx=r+dr,c+dc
                    while (yy,xx)!=(y,x):
                        out[yy][xx]=1; yy+=dr; xx+=dc
    return out

