def transform(grid):
    # Extend the row containing the long interior bar to its right edge in 1,
    # preserving any foreground markers in the suffix.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    fg = Counter(v for row in grid for v in row if v != bg).most_common(1)[0][0]
    out = [row[:] for row in grid]
    candidates=[]
    for r,row in enumerate(grid):
        run=best=0
        for v in row:
            if v==fg:
                run+=1; best=max(best,run)
            else: run=0
        cells=[c for c,v in enumerate(row) if v==fg]
        if best>=5 and cells and cells[-1]<len(row)-1:
            candidates.append((best,r,cells[-1]))
    if candidates:
        _,r,last=max(candidates)
        for c in range(last+1,len(grid[r])):
            if grid[r][c]==bg: out[r][c]=1
    return out

